1	package custody
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"os"
7		"path/filepath"
8		"sort"
9		"strings"
10		"sync"
11		"time"
12	)
13	
14	// Store 是一份本地样品数据的入口。零值不可用，请通过 Open 创建或重新打开。
15	//
16	// 同一时刻所有读写操作都由一把互斥锁串行化，因此并发操作同一样品时，
17	// 既不会超量分装，也不会出现两条待确认交接。每次成功的写操作都会
18	// 原子落盘（临时文件 + rename），关闭后重新打开同一文件即可恢复
19	// 全部样品、保管历史以及交接编号的重复提交判断。
20	type Store struct {
21		path string
22		mu   sync.Mutex
23		data *ledger
24	
25		// now 可在同包测试中替换，便于确定性地控制事件时间。
26		now func() time.Time
27	}
28	
29	// Open 打开 path 指向的本地样品数据：文件不存在时创建一份新数据，
30	// 已存在时原样重新打开，历史记录与交接编号判断继续有效。
31	func Open(path string) (*Store, error) {
32		if strings.TrimSpace(path) == "" {
33			return nil, fmt.Errorf("%w: 数据文件路径不能为空", ErrInvalid)
34		}
35	
36		s := &Store{path: path, now: time.Now}
37	
38		raw, err := os.ReadFile(path)
39		switch {
40		case err == nil:
41			var l ledger
42			if err := json.Unmarshal(raw, &l); err != nil {
43				return nil, fmt.Errorf("读取本地样品数据 %s 失败: %w", path, err)
44			}
45			if l.Version != 1 {
46				return nil, fmt.Errorf("本地样品数据 %s 的版本 %d 不受支持", path, l.Version)
47			}
48			if l.Samples == nil {
49				l.Samples = make(map[string]*sampleRecord)
50			}
51			if l.Transfers == nil {
52				l.Transfers = make(map[string]*transferRecord)
53			}
54			if err := validateRestored(&l); err != nil {
55				return nil, err
56			}
57			s.data = &l
58		case os.IsNotExist(err):
59			s.data = newLedger()
60			if err := s.persist(s.data); err != nil {
61				return nil, err
62			}
63		default:
64			return nil, fmt.Errorf("打开本地样品数据 %s 失败: %w", path, err)
65		}
66		return s, nil
67	}
68	
69	// validateRestored 校验从文件恢复的数据中销毁数量与交接关联是否一致。
70	//
71	// 每个样品先核对待确认交接，再核对销毁数量：已销毁样品仍挂着待确认交接
72	// 本身就是损坏，沿用原有的交接恢复报错。
73	//
74	// 对带有销毁信息的样品，逐一核对数量守恒（见 validateDestroyedQuantity）：
75	// 当前剩余量必须为 0.000，实际销毁量与自身初始量都大于零，且实际销毁量
76	// 加上各直接子样创建时取得的初始量之和恰好等于该样品自身的初始量。参与
77	// 核对的子样关系还必须一致：子样列表中的编号对应现存样品、其来源编号
78	// 指向本样品且不重复，来源编号指向本样品的子样也必须全部列在其中；重复
79	// 列入、来源不符或漏列都按无效数据拒绝，不能只凭数量等式接受。这里只
80	// 统计直接子样创建时的量：子样后来继续分装、转交或销毁都不改变原样
81	// 当时已经分出的量，不能改用子样当前剩余量，孙样也不重复计入；没有分出
82	// 子样的样品，实际销毁量就应等于自己的初始量。
83	//
84	// 样品的非空 PendingID 必须指向一条实际存在、尚未确认、且属于该样品的
85	// 交接；每条尚未确认的交接也必须对应一份实际存在、且 PendingID 正好指向
86	// 它的样品。待确认交接表示样品当前全部剩余量尚待指定人员接收，因此其
87	// 内容还必须与样品当前记录一致：样品未销毁、剩余量大于零、交出人等于
88	// 当前持有人、交出地点等于当前地点、交接量精确等于当前剩余量。
89	//
90	// 已确认交接属于保留的历史，不要求样品继续指向它，也不核对其与样品当前
91	// 持有人、地点或剩余量的差异（样品后来分装、移动或销毁都不能否定当时的
92	// 接收事实）；但它必须保留有效的接收信息：确认人非空且与该交接原先指定
93	// 的接收人一致，接收时间存在且非零，且按实际时刻不早于交出时间（恰好
94	// 相等合法，时区只影响表示）。集合中占用编号却为 null 的条目视为损坏，
95	// 不能当作记录不存在。任一问题都使整个文件无法恢复，绝不只加载其中
96	// 一部分，也不改动原文件。
97	func validateRestored(l *ledger) error {
98		sampleIDs := make([]string, 0, len(l.Samples))
99		for id := range l.Samples {
100			sampleIDs = append(sampleIDs, id)
101		}
102		sort.Strings(sampleIDs)
103		for _, id := range sampleIDs {
104			rec := l.Samples[id]
105			if rec == nil {
106				return fmt.Errorf("%w: 样品编号 %q 已被占用但记录为 null，无法恢复", ErrInvalid, id)
107			}
108			if rec.PendingID != "" {
109				tr, ok := l.Transfers[rec.PendingID]
110				switch {
111				case !ok:
112					return fmt.Errorf("%w: 样品 %q 记着待确认交接 %q，但该交接不存在，无法恢复",
113						ErrInvalid, id, rec.PendingID)
114				case tr == nil:
115					return fmt.Errorf("%w: 样品 %q 记着待确认交接 %q，但该交接记录为 null，无法恢复",
116						ErrInvalid, id, rec.PendingID)
117				case tr.Confirmed:
118					return fmt.Errorf("%w: 样品 %q 记着的交接 %q 已确认，不能仍是待确认，无法恢复",
119						ErrInvalid, id, rec.PendingID)
120				case tr.SampleID != id:
121					return fmt.Errorf("%w: 样品 %q 记着的待确认交接 %q 属于样品 %q，无法恢复",
122						ErrInvalid, id, rec.PendingID, tr.SampleID)
123				}
124				if err := validatePendingContent(id, rec, tr); err != nil {
125					return err
126				}
127			}
128			// 销毁数量核对放在待确认交接核对之后：已销毁样品仍挂着待确认交接
129			// 本身就是损坏，沿用原有的交接恢复报错，保持与既有交接检查的兼容。
130			if rec.Destroyed != nil {
131				if err := validateDestroyedQuantity(id, rec, l); err != nil {
132					return err
133				}
134			}
135		}
136	
137		transferIDs := make([]string, 0, len(l.Transfers))
138		for id := range l.Transfers {
139			transferIDs = append(transferIDs, id)
140		}
141		sort.Strings(transferIDs)
142		for _, id := range transferIDs {
143			rec := l.Transfers[id]
144			if rec == nil {
145				return fmt.Errorf("%w: 交接编号 %q 已被占用但记录为 null，无法恢复", ErrInvalid, id)
146			}
147			if rec.Confirmed {
148				if err := validateConfirmedReceipt(rec); err != nil {
149					return err
150				}
151				continue
152			}
153			sample, ok := l.Samples[rec.SampleID]
154			switch {
155			case !ok:
156				return fmt.Errorf("%w: 待确认交接 %q 对应的样品 %q 不存在，无法恢复",
157					ErrInvalid, id, rec.SampleID)
158			case sample == nil:
159				return fmt.Errorf("%w: 待确认交接 %q 对应的样品 %q 记录为 null，无法恢复",
160					ErrInvalid, id, rec.SampleID)
161			case sample.PendingID != id:
162				return fmt.Errorf("%w: 待确认交接 %q 的样品 %q 并未记着该交接编号，无法恢复",
163					ErrInvalid, id, rec.SampleID)
164			default:
165				if err := validatePendingContent(rec.SampleID, sample, rec); err != nil {
166					return err
167				}
168			}
169		}
170		return nil
171	}
172	
173	// validateDestroyedQuantity 核对一份带销毁信息的样品记录其数量是否守恒。
174	// 销毁处理的是样品当时的全部剩余量，因此恢复时必须满足：
175	//   - 当前剩余量为 0.000；
176	//   - 自身初始量与实际销毁量都大于零（参与核对的数量必须为正）；
177	//   - 参与数量核对的子样关系必须一致：Children 里每个编号都对应一份现存
178	//     样品，且该子样的 ParentID 正好指向本样品，每个编号在列表中只出现
179	//     一次；反过来，全数据中任何 ParentID 指向本样品的子样也必须列在
180	//     Children 里。同一编号重复列入、列入的子样来源不符（含来源为空或
181	//     指向另一份原样/样品）、漏列真正的直接子样都使来源关系自相矛盾，
182	//     即使合计碰巧等于初始量也必须拒绝；不能靠删除重复项、忽略漏列项或
183	//     改写子样来源来接受文件；
184	//   - 实际销毁量加上它直接分出的各子样创建时取得的初始量之和，恰好等于
185	//     该样品自身的初始量。
186	//
187	// 直接子样总量只在关系一致的集合上统计，取各子样记录自身的 Initial（创建
188	// 时取得的量）：子样后来继续分装、转交或销毁都不改变原样当时已经分出的
189	// 量，不能改用子样当前剩余量，孙样也不重复计入。没有分出子样时，直接
190	// 子样总量为 0，实际销毁量就应等于自身初始量。同一份数据里的其他原样
191	// 不参与本次核对。合计超过 int64 可表示范围时按无效数据拒绝，不能因数量
192	// 过大把回绕后的差额当作合法结果接受。任一不符都返回包装了 ErrInvalid
193	// 的错误，信息写明样品编号、涉及的子样编号与重复/来源不符/漏列或数量
194	// 不符的具体原因；涉及合计不一致时同时展示初始量、销毁量与直接子样
195	// 总量，统一按三位小数毫升展示。
196	func validateDestroyedQuantity(sampleID string, rec *sampleRecord, l *ledger) error {
197		const msgTail = "，无法恢复"
198		destroyedQty := rec.Destroyed.Qty
199		switch {
200		case rec.Remaining != 0:
201			return fmt.Errorf("%w: 样品 %q 已销毁但当前剩余量为 %s 毫升，已销毁样品剩余量必须为 0.000 毫升%s",
202				ErrInvalid, sampleID, formatUnits(rec.Remaining), msgTail)
203		case rec.Initial <= 0:
204			return fmt.Errorf("%w: 样品 %q 的销毁记录无法核对：样品初始量 %s 毫升必须大于零%s",
205				ErrInvalid, sampleID, formatUnits(rec.Initial), msgTail)
206		case destroyedQty <= 0:
207			return fmt.Errorf("%w: 样品 %q 的实际销毁量 %s 毫升必须大于零%s",
208				ErrInvalid, sampleID, formatUnits(destroyedQty), msgTail)
209		}
210	
211		// 先确认参与数量核对的子样集合关系一致，再统计它们创建时取得的初始
212		// 量：数量等式成立也不能掩盖重复列入、来源不符或漏列。
213		listed := make(map[string]struct{}, len(rec.Children))
214		for _, childID := range rec.Children {
215			if _, dup := listed[childID]; dup {
216				return fmt.Errorf("%w: 样品 %q 的销毁数量核对中，直接子样编号 %q 在子样列表中重复列入，同一子样只能计入一次%s",
217					ErrInvalid, sampleID, childID, msgTail)
218			}
219			listed[childID] = struct{}{}
220			child, ok := l.Samples[childID]
221			if !ok || child == nil {
222				return fmt.Errorf("%w: 样品 %q 的销毁数量核对中，列入的直接子样 %q 不存在%s",
223					ErrInvalid, sampleID, childID, msgTail)
224			}
225			if child.ParentID != sampleID {
226				if child.ParentID == "" {
227					return fmt.Errorf("%w: 样品 %q 的销毁数量核对中，列入的子样 %q 是原样、没有来源编号，不是由样品 %q 直接分出的子样%s",
228						ErrInvalid, sampleID, childID, sampleID, msgTail)
229				}
230				return fmt.Errorf("%w: 样品 %q 的销毁数量核对中，列入的子样 %q 来源编号为 %q，不是由样品 %q 直接分出的子样%s",
231					ErrInvalid, sampleID, childID, child.ParentID, sampleID, msgTail)
232			}
233		}
234		// 反向核对：任何真正由本样品分出的子样都必须列在子样列表中，漏列会
235		// 让查询出的来源关系互相矛盾，不能因数量等式成立而接受。
236		for otherID, other := range l.Samples {
237			if other == nil || other.ParentID != sampleID {
238				continue
239			}
240			if _, ok := listed[otherID]; !ok {
241				return fmt.Errorf("%w: 样品 %q 的销毁数量核对中，子样 %q 的来源编号指向样品 %q，却没有列在样品 %q 的直接子样列表中，属于漏列%s",
242					ErrInvalid, sampleID, otherID, sampleID, sampleID, msgTail)
243			}
244		}
245	
246		// 只统计关系一致的直接子样创建时取得的初始量；子样后续变化与孙样都
247		// 不计入。
248		var directChildrenTotal int64
249		for _, childID := range rec.Children {
250			child := l.Samples[childID]
251			if child.Initial <= 0 {
252				return fmt.Errorf("%w: 样品 %q 的直接子样 %q 初始量 %s 毫升必须大于零，无法核对销毁数量%s",
253					ErrInvalid, sampleID, childID, formatUnits(child.Initial), msgTail)
254			}
255			next := directChildrenTotal + child.Initial
256			if next < 0 || next < directChildrenTotal {
257				return fmt.Errorf("%w: 样品 %q 的销毁数量核对中，实际销毁量 %s 毫升与直接子样总量合计超出可表示范围%s",
258					ErrInvalid, sampleID, formatUnits(destroyedQty), msgTail)
259			}
260			directChildrenTotal = next
261		}
262	
263		total := destroyedQty + directChildrenTotal
264		if total < 0 || total < destroyedQty {
265			return fmt.Errorf("%w: 样品 %q 的销毁数量核对中，实际销毁量 %s 毫升与直接子样总量 %s 毫升合计超出可表示范围%s",
266				ErrInvalid, sampleID, formatUnits(destroyedQty),
267				formatUnits(directChildrenTotal), msgTail)
268		}
269		if total != rec.Initial {
270			return fmt.Errorf("%w: 样品 %q 的销毁数量与分装记录不符：初始量 %s 毫升，实际销毁量 %s 毫升，直接子样总量 %s 毫升，实际销毁量与直接子样总量之和应为 %s 毫升%s",
271				ErrInvalid, sampleID,
272				formatUnits(rec.Initial), formatUnits(destroyedQty),
273				formatUnits(directChildrenTotal), formatUnits(rec.Initial), msgTail)
274		}
275		return nil
276	}
277	
278	// validatePendingContent 核对一条待确认交接的内容是否与样品当前记录一致。
279	// 待确认交接表示样品当前全部剩余量尚待指定人员接收：样品必须未销毁且
280	// 剩余量大于零，交接的交出人、交出地点和交接量必须分别精确等于样品的
281	// 当前持有人、当前地点和当前剩余量。任一不符都返回包装了 ErrInvalid 的
282	// 错误，并在信息中写明样品编号、交接编号以及冲突项（人员、地点、数量
283	// 或销毁状态）；数量冲突同时列出双方数量，统一按三位小数毫升展示。
284	func validatePendingContent(sampleID string, sample *sampleRecord, tr *transferRecord) error {
285		switch {
286		case sample.Destroyed != nil:
287			return fmt.Errorf("%w: 样品 %q 的待确认交接 %q 仍存在，但样品已销毁，无法恢复",
288				ErrInvalid, sampleID, tr.ID)
289		case sample.Remaining <= 0:
290			return fmt.Errorf("%w: 样品 %q 的待确认交接 %q 仍存在，但样品当前剩余量为 %s 毫升（未销毁），无法恢复",
291				ErrInvalid, sampleID, tr.ID, formatUnits(sample.Remaining))
292		case tr.FromHolder != sample.Holder:
293			return fmt.Errorf("%w: 样品 %q 的待确认交接 %q 的交出人 %q 与样品当前持有人 %q 不一致，无法恢复",
294				ErrInvalid, sampleID, tr.ID, tr.FromHolder, sample.Holder)
295		case tr.FromLocation != sample.Location:
296			return fmt.Errorf("%w: 样品 %q 的待确认交接 %q 的交出地点 %q 与样品当前地点 %q 不一致，无法恢复",
297				ErrInvalid, sampleID, tr.ID, tr.FromLocation, sample.Location)
298		case tr.Qty != sample.Remaining:
299			return fmt.Errorf("%w: 样品 %q 的待确认交接 %q 的交接量 %s 毫升与样品当前剩余量 %s 毫升不一致，无法恢复",
300				ErrInvalid, sampleID, tr.ID, formatUnits(tr.Qty), formatUnits(sample.Remaining))
301		}
302		return nil
303	}
304	
305	// validateConfirmedReceipt 核对一条已确认交接是否保留了有效的接收事实。
306	// 已确认表示样品确实完成过一次转手，因此确认人必须非空（去首尾空白后）
307	// 且与该交接原先指定的接收人完全一致，接收时间必须存在且不是零时间，
308	// 并按实际时刻不早于交出时间（恰好相等合法；不同时区表示同一时刻也算
309	// 相等，时间倒置用 Before 判断而非比较时区偏移后的字面值）。任一不符
310	// 都返回包装了 ErrInvalid 的错误，信息写明交接编号、关联样品编号以及
311	// 具体问题（缺少/空白确认人、确认人不符、缺少或零值接收时间、时间倒置），
312	// 绝不靠补写确认人、猜测接收时间或改回待确认来接受异常记录。
313	func validateConfirmedReceipt(tr *transferRecord) error {
314		switch {
315		case tr.ConfirmedBy == "":
316			return fmt.Errorf("%w: 已确认交接 %q（样品 %q）缺少确认人，无法恢复",
317				ErrInvalid, tr.ID, tr.SampleID)
318		case strings.TrimSpace(tr.ConfirmedBy) == "":
319			return fmt.Errorf("%w: 已确认交接 %q（样品 %q）的确认人不能只有空白，无法恢复",
320				ErrInvalid, tr.ID, tr.SampleID)
321		case tr.ConfirmedBy != tr.ToHolder:
322			return fmt.Errorf("%w: 已确认交接 %q（样品 %q）的确认人 %q 与原定接收人 %q 不一致，无法恢复",
323				ErrInvalid, tr.ID, tr.SampleID, tr.ConfirmedBy, tr.ToHolder)
324		}
325		switch {
326		case tr.ReceivedAt == nil:
327			return fmt.Errorf("%w: 已确认交接 %q（样品 %q）缺少接收时间，无法恢复",
328				ErrInvalid, tr.ID, tr.SampleID)
329		case tr.ReceivedAt.IsZero():
330			return fmt.Errorf("%w: 已确认交接 %q（样品 %q）的接收时间为零值，无法恢复",
331				ErrInvalid, tr.ID, tr.SampleID)
332		case tr.ReceivedAt.Before(tr.HandedOverAt):
333			return fmt.Errorf("%w: 已确认交接 %q（样品 %q）的接收时间 %s 早于交出时间 %s，无法恢复",
334				ErrInvalid, tr.ID, tr.SampleID,
335				tr.ReceivedAt.Format(time.RFC3339), tr.HandedOverAt.Format(time.RFC3339))
336		}
337		return nil
338	}
