340	// persist 把整份状态原子写入文件：先写同目录临时文件，再 rename 覆盖，
341	// 避免进程中断留下半截数据。
342	func (s *Store) persist(l *ledger) error {
343		raw, err := json.MarshalIndent(l, "", "  ")
344		if err != nil {
345			return fmt.Errorf("编码本地样品数据失败: %w", err)
346		}
347	
348		dir := filepath.Dir(s.path)
349		tmp, err := os.CreateTemp(dir, ".custody-*.tmp")
350		if err != nil {
351			return fmt.Errorf("创建临时数据文件失败: %w", err)
352		}
353		tmpName := tmp.Name()
354		defer os.Remove(tmpName)
355	
356		if _, err := tmp.Write(raw); err != nil {
357			tmp.Close()
358			return fmt.Errorf("写入临时数据文件失败: %w", err)
359		}
360		if err := tmp.Close(); err != nil {
361			return fmt.Errorf("关闭临时数据文件失败: %w", err)
362		}
363		if err := os.Rename(tmpName, s.path); err != nil {
364			return fmt.Errorf("替换本地样品数据文件失败: %w", err)
365		}
366		return nil
367	}
