369	// commit 在候选状态上落盘并替换内存状态。调用方必须保证 candidate
370	// 已通过全部校验；落盘失败时内存状态保持不变。
371	func (s *Store) commit(candidate *ledger) error {
372		if err := s.persist(candidate); err != nil {
373			return err
374		}
375		s.data = candidate
376		return nil
377	}
