379	// RegisterInput 是登记原样的入参。
380	type RegisterInput struct {
381		// ID 为样品编号，在这份数据内唯一，去空白后非空。
382		ID string
383		// Qty 为初始数量（毫升），大于零、最多三位小数的十进制字符串。
384		Qty string
385		// Holder 为初始持有人，去空白后非空。
386		Holder string
