391	// Register 登记一份原样。编号重复等冲突返回包装了 ErrConflict 的错误，
392	// 且不会写入任何记录。
393	func (s *Store) Register(in RegisterInput) (*Sample, error) {
394		s.mu.Lock()
395		defer s.mu.Unlock()
396	
397		id, err := trimRequired("样品编号", in.ID)
398		if err != nil {
399			return nil, err
400		}
401		holder, err := trimRequired("持有人", in.Holder)
402		if err != nil {
403			return nil, err
404		}
405		location, err := trimRequired("地点", in.Location)
406		if err != nil {
407			return nil, err
408		}
409		qty, err := parseQuantity(in.Qty)
410		if err != nil {
411			return nil, err
412		}
413		if _, exists := s.data.Samples[id]; exists {
414			return nil, fmt.Errorf("%w: 样品编号 %q 已存在", ErrConflict, id)
415		}
416	
417		candidate := s.data.deepCopy()
418		now := s.now().UTC()
419		candidate.Samples[id] = &sampleRecord{
420			ID:        id,
421			Initial:   qty,
422			Remaining: qty,
423			Holder:    holder,
424			Location:  location,
425			Children:  []string{},
426			History: []historyRecord{{
427				Kind:     "register",
428				Time:     now,
429				Holder:   holder,
430				Location: location,
431				Detail:   "登记原样",
432			}},
433		}
434		if err := s.commit(candidate); err != nil {
435			return nil, err
436		}
437		return buildSampleView(candidate.Samples[id], candidate), nil
438	}
