440	// SplitPart 是一次分装中的一个子样。
441	type SplitPart struct {
442		// ID 为子样编号，在这份数据内唯一，去空白后非空。
443		ID string
444		// Qty 为该子样数量（毫升），大于零、最多三位小数。
445		Qty string
446	}
447	
448	// SplitInput 是一次分装的入参；一次分装可以同时创建多个子样。
449	type SplitInput struct {
450		// ParentID 为来源样品编号。
451		ParentID string
452		// Parts 为本次要创建的全部子样，至少一个。
453		Parts []SplitPart
454	}
455	
456	// Split 执行一次原子分装。任一子样编号重复、数量不合法或子样总量超过
457	// 来源样品剩余量时，整次分装都不生效。成功后来源样品按整数刻度精确
458	// 扣减，子样继承当时的持有人和地点，并可继续分装。
459	//
460	// 返回来源样品的最新视图；子样可通过 GetSample 分别查询。
461	func (s *Store) Split(in SplitInput) (*Sample, error) {
462		s.mu.Lock()
463		defer s.mu.Unlock()
464	
465		parentID, err := trimRequired("来源样品编号", in.ParentID)
466		if err != nil {
467			return nil, err
468		}
469		if len(in.Parts) == 0 {
470			return nil, fmt.Errorf("%w: 一次分装至少要创建一个子样", ErrInvalid)
471		}
472	
473		parent, ok := s.data.Samples[parentID]
474		if !ok {
475			return nil, fmt.Errorf("%w: 来源样品 %q 不存在", ErrNotFound, parentID)
476		}
477	
478		// 先在局部完成全部校验，任何一项不通过都直接返回，不动状态。
479		type parsedPart struct {
480			id  string
481			qty int64
482		}
483		parsed := make([]parsedPart, 0, len(in.Parts))
484		seen := make(map[string]struct{}, len(in.Parts))
485		var total int64
486		for _, p := range in.Parts {
487			id, err := trimRequired("子样编号", p.ID)
488			if err != nil {
489				return nil, err
490			}
491			if _, dup := seen[id]; dup {
492				return nil, fmt.Errorf("%w: 本次分装中子样编号 %q 重复", ErrInvalid, id)
493			}
494			if _, exists := s.data.Samples[id]; exists {
495				return nil, fmt.Errorf("%w: 子样编号 %q 已存在", ErrConflict, id)
496			}
497			if id == parentID {
498				return nil, fmt.Errorf("%w: 子样编号 %q 不能与来源样品相同", ErrInvalid, id)
499			}
500			qty, err := parseQuantity(p.Qty)
501			if err != nil {
502				return nil, err
503			}
504			seen[id] = struct{}{}
505			parsed = append(parsed, parsedPart{id: id, qty: qty})
506			total += qty
507			if total < 0 {
508				return nil, fmt.Errorf("%w: 子样总量超出可表示范围", ErrInvalid)
509			}
510		}
511	
512		if parent.Destroyed != nil {
513			return nil, fmt.Errorf("%w: 样品 %q 已销毁，不能再分装", ErrConflict, parentID)
514		}
515		if parent.PendingID != "" {
516			return nil, fmt.Errorf("%w: 样品 %q 存在待确认交接 %s，不能分装",
517				ErrConflict, parentID, parent.PendingID)
518		}
519		if parent.Remaining == 0 {
520			return nil, fmt.Errorf("%w: 样品 %q 剩余量为零，不能再分装", ErrConflict, parentID)
521		}
522		if total > parent.Remaining {
523			return nil, fmt.Errorf("%w: 子样总量 %s 毫升超过样品 %q 的剩余量 %s 毫升",
524				ErrConflict, formatUnits(total), parentID, formatUnits(parent.Remaining))
525		}
526	
527		candidate := s.data.deepCopy()
528		cpParent := candidate.Samples[parentID]
529		now := s.now().UTC()
530	
531		childIDs := make([]string, 0, len(parsed))
532		for _, p := range parsed {
533			childIDs = append(childIDs, p.id)
534			candidate.Samples[p.id] = &sampleRecord{
535				ID:        p.id,
536				ParentID:  parentID,
537				Initial:   p.qty,
538				Remaining: p.qty,
539				Holder:    cpParent.Holder,
540				Location:  cpParent.Location,
541				Children:  []string{},
542				History: []historyRecord{{
543					Kind:     "split",
544					Time:     now,
545					Holder:   cpParent.Holder,
546					Location: cpParent.Location,
547					Detail:   fmt.Sprintf("由样品 %s 分装", parentID),
548				}},
549			}
550		}
551		cpParent.Remaining -= total
552		cpParent.Children = append(cpParent.Children, childIDs...)
553		cpParent.History = append(cpParent.History, historyRecord{
554			Kind:     "split",
555			Time:     now,
556			Holder:   cpParent.Holder,
557			Location: cpParent.Location,
558			Detail:   fmt.Sprintf("分装创建子样 %s", strings.Join(childIDs, ", ")),
559		})
560	
561		if err := s.commit(candidate); err != nil {
562			return nil, err
563		}
564		return buildSampleView(cpParent, candidate), nil
565	}
