567	// HandoverInput 是发起交接（交出）的入参。
568	type HandoverInput struct {
569		// TransferID 为本次交接编号，在本地数据中唯一，去空白后非空。
570		TransferID string
571		// SampleID 为要交出的样品编号。
572		SampleID string
573		// FromHolder 为交出人，必须与样品当前持有人完全一致（比较前对入参去空白）。
574		FromHolder string
575		// FromLocation 为交出地点，必须与样品当前地点完全一致。
576		FromLocation string
577		// ToHolder 为指定接收人，不能与交出人相同。
578		ToHolder string
579		// ToLocation 为目的地点。
580		ToLocation string
581		// HandedOverAt 为交出时间。
582		HandedOverAt time.Time
583	}
584	
585	// Handover 发起一次交接：转移该样品的全部剩余量，交接进入待确认状态，
586	// 原持有人和地点保持不变，直到指定接收人在目的地点确认。
587	//
588	// 交接编号已存在时：内容（样品、人员、地点、时间）完全一致则原样返回
589	// 既有交接（无论是否已确认）；任一内容不同则拒绝。
590	func (s *Store) Handover(in HandoverInput) (*TransferView, error) {
591		s.mu.Lock()
592		defer s.mu.Unlock()
593	
594		transferID, err := trimRequired("交接编号", in.TransferID)
595		if err != nil {
596			return nil, err
597		}
598		sampleID, err := trimRequired("样品编号", in.SampleID)
599		if err != nil {
600			return nil, err
601		}
602		fromHolder, err := trimRequired("交出人", in.FromHolder)
603		if err != nil {
604			return nil, err
605		}
606		fromLocation, err := trimRequired("交出地点", in.FromLocation)
607		if err != nil {
608			return nil, err
609		}
610		toHolder, err := trimRequired("接收人", in.ToHolder)
611		if err != nil {
612			return nil, err
613		}
614		toLocation, err := trimRequired("目的地点", in.ToLocation)
615		if err != nil {
616			return nil, err
617		}
618		if in.HandedOverAt.IsZero() {
619			return nil, fmt.Errorf("%w: 交出时间不能为空", ErrInvalid)
620		}
621		handedAt := in.HandedOverAt.UTC()
622	
623		if existing, ok := s.data.Transfers[transferID]; ok {
624			if !sameHandoverRequest(existing, sampleID, fromHolder, fromLocation, toHolder, toLocation, handedAt) {
625				return nil, fmt.Errorf("%w: 交接编号 %q 已被内容不同的交接使用", ErrConflict, transferID)
626			}
627			// 完全相同的重复提交：返回原交接，不增加任何记录。
628			return buildTransferView(existing), nil
629		}
630	
631		sample, ok := s.data.Samples[sampleID]
632		if !ok {
633			return nil, fmt.Errorf("%w: 样品 %q 不存在", ErrNotFound, sampleID)
634		}
635		if sample.Destroyed != nil {
636			return nil, fmt.Errorf("%w: 样品 %q 已销毁，不能发起新的交接", ErrConflict, sampleID)
637		}
638		if sample.Remaining == 0 {
639			return nil, fmt.Errorf("%w: 样品 %q 剩余量为零，不能发起交接", ErrConflict, sampleID)
640		}
641		if sample.PendingID != "" {
642			return nil, fmt.Errorf("%w: 样品 %q 已存在待确认交接 %s",
643				ErrConflict, sampleID, sample.PendingID)
644		}
645		if sample.Holder != fromHolder {
646			return nil, fmt.Errorf("%w: 交出人 %q 与样品 %q 当前持有人 %q 不一致",
647				ErrInvalid, fromHolder, sampleID, sample.Holder)
648		}
649		if sample.Location != fromLocation {
650			return nil, fmt.Errorf("%w: 交出地点 %q 与样品 %q 当前地点 %q 不一致",
651				ErrInvalid, fromLocation, sampleID, sample.Location)
652		}
653		if toHolder == fromHolder {
654			return nil, fmt.Errorf("%w: 接收人不能与交出人 %q 相同", ErrInvalid, fromHolder)
655		}
656	
657		candidate := s.data.deepCopy()
658		rec := &transferRecord{
659			ID:           transferID,
660			SampleID:     sampleID,
661			FromHolder:   fromHolder,
662			FromLocation: fromLocation,
663			ToHolder:     toHolder,
664			ToLocation:   toLocation,
665			Qty:          sample.Remaining,
666			HandedOverAt: handedAt,
667		}
668		candidate.Transfers[transferID] = rec
669		cpSample := candidate.Samples[sampleID]
670		cpSample.PendingID = transferID
671		cpSample.History = append(cpSample.History, historyRecord{
672			Kind:     "transfer-out",
673			Time:     handedAt,
674			Holder:   fromHolder,
675			Location: fromLocation,
676			Detail:   fmt.Sprintf("发起交接 %s，待 %s 在 %s 接收", transferID, toHolder, toLocation),
677		})
678	
679		if err := s.commit(candidate); err != nil {
680			return nil, err
681		}
682		return buildTransferView(rec), nil
683	}
684	
685	// sameHandoverRequest 判断已存交接与本次请求的内容是否完全相同。
686	func sameHandoverRequest(t *transferRecord, sampleID, fromHolder, fromLocation, toHolder, toLocation string, handedAt time.Time) bool {
687		return t.SampleID == sampleID &&
688			t.FromHolder == fromHolder &&
689			t.FromLocation == fromLocation &&
690			t.ToHolder == toHolder &&
691			t.ToLocation == toLocation &&
692			t.HandedOverAt.Equal(handedAt)
693	}
694	
695	// ConfirmInput 是确认接收的入参。
696	type ConfirmInput struct {
697		// TransferID 为待确认的交接编号。
698		TransferID string
699		// Receiver 为实际接收人，必须是发起时指定的接收人。
700		Receiver string
701		// AtLocation 为接收地点，必须是发起时的目的地点。
702		AtLocation string
703		// ReceivedAt 为接收时间，不能早于交出时间。
704		ReceivedAt time.Time
705	}
706	
707	// Confirm 由指定接收人在目的地点确认接收。确认后样品的持有人和地点
708	// 才真正改变，待确认状态结束。
709	//
710	// 对已确认交接重复提交完全相同的接收信息（接收人、地点、时间）时，
711	// 返回原结果且不增加转手记录；信息不同则拒绝。
712	func (s *Store) Confirm(in ConfirmInput) (*TransferView, error) {
713		s.mu.Lock()
714		defer s.mu.Unlock()
715	
716		transferID, err := trimRequired("交接编号", in.TransferID)
717		if err != nil {
718			return nil, err
719		}
720		receiver, err := trimRequired("接收人", in.Receiver)
721		if err != nil {
722			return nil, err
723		}
724		atLocation, err := trimRequired("接收地点", in.AtLocation)
725		if err != nil {
726			return nil, err
727		}
728		if in.ReceivedAt.IsZero() {
729			return nil, fmt.Errorf("%w: 接收时间不能为空", ErrInvalid)
730		}
731		receivedAt := in.ReceivedAt.UTC()
732	
733		rec, ok := s.data.Transfers[transferID]
734		if !ok {
735			// 明确的不存在错误，绝不顺带创建交接。
736			return nil, fmt.Errorf("%w: 交接 %q 不存在", ErrNotFound, transferID)
737		}
738	
739		if rec.Confirmed {
740			same := rec.ConfirmedBy == receiver &&
741				rec.ToLocation == atLocation &&
742				rec.ReceivedAt != nil && rec.ReceivedAt.Equal(receivedAt)
743			if !same {
744				return nil, fmt.Errorf("%w: 交接 %q 已确认，接收信息与原确认不一致", ErrConflict, transferID)
745			}
746			return buildTransferView(rec), nil
747		}
748	
749		if receiver != rec.ToHolder {
750			return nil, fmt.Errorf("%w: 只有指定接收人 %q 能确认交接 %q，实际确认人为 %q",
751				ErrConflict, rec.ToHolder, transferID, receiver)
752		}
753		if atLocation != rec.ToLocation {
754			return nil, fmt.Errorf("%w: 必须在目的地点 %q 确认交接 %q，实际地点为 %q",
755				ErrConflict, rec.ToLocation, transferID, atLocation)
756		}
757		if receivedAt.Before(rec.HandedOverAt) {
758			return nil, fmt.Errorf("%w: 接收时间不能早于交出时间 %s",
759				ErrInvalid, rec.HandedOverAt.Format(time.RFC3339))
760		}
761	
762		candidate := s.data.deepCopy()
763		cp := candidate.Transfers[transferID]
764		cp.Confirmed = true
765		cp.ConfirmedBy = receiver
766		receivedAtCopy := receivedAt
767		cp.ReceivedAt = &receivedAtCopy
768	
769		sample := candidate.Samples[cp.SampleID]
770		sample.Holder = receiver
771		sample.Location = atLocation
772		sample.PendingID = ""
773		sample.History = append(sample.History, historyRecord{
774			Kind:     "transfer-in",
775			Time:     receivedAt,
776			Holder:   receiver,
777			Location: atLocation,
778			Detail:   fmt.Sprintf("交接 %s 确认接收（交出时间 %s）", transferID, cp.HandedOverAt.Format(time.RFC3339)),
779		})
780	
781		if err := s.commit(candidate); err != nil {
782			return nil, err
783		}
784		return buildTransferView(cp), nil
785	}
786	
787	// DestroyInput 是销毁样品全部剩余量的入参；销毁不接受部分销毁。
788	type DestroyInput struct {
789		// SampleID 为样品编号。
790		SampleID string
791		// Operator 为操作人，去空白后必须与样品当前持有人一致。
792		Operator string
793		// Location 为销毁所在地点，去空白后必须与样品当前地点一致。
794		Location string
795		// At 为销毁时间，不能为零，也不能早于该样品任何已有保管历史的时间。
796		At time.Time
797		// Reason 为销毁原因，去空白后非空。
798		Reason string
799	}
800	
801	// Destroy 销毁该编号样品当时的全部剩余量（不接受部分销毁）。成功后
802	// 剩余量变为 0.000，初始量、来源关系、子样列表与原有保管历史保留，
803	// 持有人和地点保留为销毁前的最后记录，并在保管历史末尾追加一次销毁
804	// 事件；返回该样品的最新查询结果。
805	//
806	// 已销毁样品重复提交完全相同的操作人、地点、时间和原因时，返回原销毁
807	// 结果且不再追加历史；文本按去首尾空白后的内容比较，时间按实际时刻
808	// 比较。任一项不同则返回 ErrConflict，不覆盖原记录。
809	func (s *Store) Destroy(in DestroyInput) (*Sample, error) {
810		s.mu.Lock()
811		defer s.mu.Unlock()
812	
813		sampleID, err := trimRequired("样品编号", in.SampleID)
814		if err != nil {
815			return nil, err
816		}
817		operator, err := trimRequired("操作人", in.Operator)
818		if err != nil {
819			return nil, err
820		}
821		location, err := trimRequired("所在地点", in.Location)
822		if err != nil {
823			return nil, err
824		}
825		reason, err := trimRequired("销毁原因", in.Reason)
826		if err != nil {
827			return nil, err
828		}
829		if in.At.IsZero() {
830			return nil, fmt.Errorf("%w: 销毁时间不能为空", ErrInvalid)
831		}
832		at := in.At.UTC()
833	
834		rec, ok := s.data.Samples[sampleID]
835		if !ok {
836			return nil, fmt.Errorf("%w: 样品 %q 不存在", ErrNotFound, sampleID)
837		}
838	
839		// 已销毁：只接受与首次销毁完全相同的重复提交，原样返回且不再追加历史。
840		if rec.Destroyed != nil {
841			if !sameDestruction(rec.Destroyed, operator, location, at, reason) {
842				return nil, fmt.Errorf("%w: 样品 %q 已销毁，本次销毁信息与原销毁记录不一致",
843					ErrConflict, sampleID)
844			}
845			return buildSampleView(rec, s.data), nil
846		}
847	
848		// 未销毁样品的状态冲突（持有人/地点不匹配按入参语义归入冲突类）。
849		if operator != rec.Holder {
850			return nil, fmt.Errorf("%w: 操作人 %q 与样品 %q 当前持有人 %q 不一致",
851				ErrConflict, operator, sampleID, rec.Holder)
852		}
853		if location != rec.Location {
854			return nil, fmt.Errorf("%w: 销毁地点 %q 与样品 %q 当前地点 %q 不一致",
855				ErrConflict, location, sampleID, rec.Location)
856		}
857		if rec.PendingID != "" {
858			return nil, fmt.Errorf("%w: 样品 %q 存在待确认交接 %s，不能销毁",
859				ErrConflict, sampleID, rec.PendingID)
860		}
861		if rec.Remaining == 0 {
862			return nil, fmt.Errorf("%w: 样品 %q 剩余量已为零且未销毁，不能再销毁",
863				ErrConflict, sampleID)
864		}
865		for _, h := range rec.History {
866			if at.Before(h.Time) {
867				return nil, fmt.Errorf("%w: 销毁时间不能早于样品 %q 已有保管历史的时间 %s",
868					ErrInvalid, sampleID, h.Time.Format(time.RFC3339))
869			}
870		}
871	
872		candidate := s.data.deepCopy()
873		cp := candidate.Samples[sampleID]
874		destroyedQty := cp.Remaining
875		cp.Remaining = 0
876		cp.Destroyed = &destructionRecord{
877			Operator: operator,
878			Location: location,
879			At:       at,
880			Reason:   reason,
881			Qty:      destroyedQty,
882		}
883		// 持有人和地点保留为销毁前的最后记录，仅在历史末尾追加销毁事件。
884		cp.History = append(cp.History, historyRecord{
885			Kind:     "destroy",
886			Time:     at,
887			Holder:   operator,
888			Location: location,
889			Detail:   fmt.Sprintf("销毁全部剩余量 %s 毫升，原因：%s", formatUnits(destroyedQty), reason),
890		})
891	
892		if err := s.commit(candidate); err != nil {
893			return nil, err
894		}
895		return buildSampleView(cp, candidate), nil
896	}
897	
898	// sameDestruction 判断本次销毁请求与已有销毁记录是否完全相同。
899	// 文本字段均已去首尾空白，时间按实际时刻（Equal）比较。
900	func sameDestruction(d *destructionRecord, operator, location string, at time.Time, reason string) bool {
901		return d.Operator == operator &&
902			d.Location == location &&
903			d.At.Equal(at) &&
904			d.Reason == reason
905	}
906	
907	// GetSample 按样品编号查询：返回来源关系、初始量/剩余量、当前持有人和
908	// 地点、直接子样、按发生顺序排列的保管历史，以及待确认交接详情。
909	// 样品不存在时返回包装了 ErrNotFound 的错误，不会创建任何记录。
910	func (s *Store) GetSample(id string) (*Sample, error) {
911		s.mu.Lock()
912		defer s.mu.Unlock()
913	
914		sampleID, err := trimRequired("样品编号", id)
915		if err != nil {
916			return nil, err
917		}
918		rec, ok := s.data.Samples[sampleID]
919		if !ok {
920			return nil, fmt.Errorf("%w: 样品 %q 不存在", ErrNotFound, sampleID)
921		}
922		return buildSampleView(rec, s.data), nil
923	}
924	
925	// GetTransfer 按交接编号查询交接详情（待确认或已确认）。
926	// 交接不存在时返回包装了 ErrNotFound 的错误，不会创建任何记录。
927	func (s *Store) GetTransfer(id string) (*TransferView, error) {
928		s.mu.Lock()
929		defer s.mu.Unlock()
930	
931		transferID, err := trimRequired("交接编号", id)
932		if err != nil {
933			return nil, err
934		}
935		rec, ok := s.data.Transfers[transferID]
936		if !ok {
937			return nil, fmt.Errorf("%w: 交接 %q 不存在", ErrNotFound, transferID)
938		}
939		return buildTransferView(rec), nil
940	}
941	
942	// buildSampleView 把内部样品记录转换为对外视图，数量统一格式化为三位小数。
943	func buildSampleView(r *sampleRecord, l *ledger) *Sample {
944		children := append([]string{}, r.Children...)
945		history := make([]History, 0, len(r.History))
946		for _, h := range r.History {
947			history = append(history, History{
948				Kind:     h.Kind,
949				Time:     h.Time,
950				Holder:   h.Holder,
951				Location: h.Location,
952				Detail:   h.Detail,
953			})
954		}
955		v := &Sample{
956			ID:         r.ID,
957			ParentID:   r.ParentID,
958			InitialQty: formatUnits(r.Initial),
959			Remaining:  formatUnits(r.Remaining),
960			Holder:     r.Holder,
961			Location:   r.Location,
962			Children:   children,
963			History:    history,
964		}
965		if r.PendingID != "" {
966			if t, ok := l.Transfers[r.PendingID]; ok {
967				v.PendingTransfer = buildTransferView(t)
968			}
969		}
970		if r.Destroyed != nil {
971			v.Destruction = &Destruction{
972				Operator: r.Destroyed.Operator,
973				Location: r.Destroyed.Location,
974				At:       r.Destroyed.At,
975				Reason:   r.Destroyed.Reason,
976				Qty:      formatUnits(r.Destroyed.Qty),
977			}
978		}
979		return v
980	}
981	
982	// buildTransferView 把内部交接记录转换为对外视图。
983	func buildTransferView(r *transferRecord) *TransferView {
984		v := &TransferView{
985			TransferID:   r.ID,
986			SampleID:     r.SampleID,
987			FromHolder:   r.FromHolder,
988			FromLocation: r.FromLocation,
989			ToHolder:     r.ToHolder,
990			ToLocation:   r.ToLocation,
991			Qty:          formatUnits(r.Qty),
992			HandedOverAt: r.HandedOverAt,
993			Confirmed:    r.Confirmed,
994			ConfirmedBy:  r.ConfirmedBy,
995		}
996		if r.ReceivedAt != nil {
997			rx := *r.ReceivedAt
998			v.ReceivedAt = &rx
999			v.ConfirmedAt = r.ToLocation
1000		}
1001		return v
1002	}
