	"strconv"
	"strings"
	"testing"
)

func openRaw(t *testing.T, content string) (*Store, error) {
	t.Helper()
	path := filepath.Join(t.TempDir(), "d.json")
	if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
		t.Fatal(err)
	}
