}

const baseSample = `"id":"S1","initial":10000,"remaining":%s,"holder":"h","location":"l","children":[],"history":[]`

func TestNewQuantityRules(t *testing.T) {
	cases := []struct {
		name     string
		sample   string
		mentions []string
	}{
		{"剩余量超过初始量", strings.Replace(baseSample, "%s", "12000", 1), []string{"S1", "12.000", "10.000", "初始量"}},
		{"剩余量为负", strings.Replace(baseSample, "%s", "-1", 1), []string{"S1", "-0.001", "负"}},
		{"初始量为零", `"id":"S1","initial":0,"remaining":0,"holder":"h","location":"l","children":[],"history":[]`, []string{"S1", "0.000", "初始量"}},
		{"初始量为负", `"id":"S1","initial":-500,"remaining":0,"holder":"h","location":"l","children":[],"history":[]`, []string{"S1", "-0.500", "初始量"}},
		{"极端负剩余量", strings.Replace(baseSample, "%s", strconv.FormatInt(math.MinInt64, 10), 1), []string{"S1", "-9223372036854775.808"}},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			s, err := openRaw(t, `{"version":1,"samples":{"S1":{`+c.sample+`}},"transfers":{}}`)
			if err == nil || s != nil {
				t.Fatalf("应拒绝打开, store=%v err=%v", s, err)
			}
			if !errors.Is(err, ErrInvalid) {
				t.Fatalf("应为 ErrInvalid: %v", err)
			}
			for _, m := range c.mentions {
				if !strings.Contains(err.Error(), m) {
					t.Fatalf("错误应提及 %q: %v", m, err)
				}
			}
		})
	}
}

func TestNewQuantityRulesChildUsesOwnInitial(t *testing.T) {
	// 子样自身初始量 3.250，剩余量 5.000 不超过父样初始量但超过自身初始量。
	s, err := openRaw(t, `{"version":1,"samples":{
		"P":{"id":"P","initial":10000,"remaining":6750,"holder":"h","location":"l","children":["C"],"history":[]},
		"C":{"id":"C","parentId":"P","initial":3250,"remaining":5000,"holder":"h","location":"l","children":[],"history":[]}
	},"transfers":{}}`)
	if err == nil || s != nil {
		t.Fatalf("子样越界应拒绝, store=%v err=%v", s, err)
	}
	if !errors.Is(err, ErrInvalid) || !strings.Contains(err.Error(), "C") || !strings.Contains(err.Error(), "5.000") || !strings.Contains(err.Error(), "3.250") {
		t.Fatalf("错误内容不符: %v", err)
	}
}

func TestNewQuantityRulesPendingMatchingBadRemaining(t *testing.T) {
	// 待确认交接量与越界剩余量一致，也不能接受。
	s, err := openRaw(t, `{"version":1,"samples":{
