	}}`)
	if err == nil || s != nil {
		t.Fatalf("交接量一致也不能接受越界数量, store=%v err=%v", s, err)
	}
	if !errors.Is(err, ErrInvalid) {
		t.Fatalf("应为 ErrInvalid: %v", err)
	}
}

func TestNewQuantityRulesValidBoundary(t *testing.T) {
	// 剩余量等于初始量、零剩余量（无销毁信息、无子样）均应正常打开。
	s, err := openRaw(t, `{"version":1,"samples":{
		"FULL":{"id":"FULL","initial":10000,"remaining":10000,"holder":"h","location":"l","children":[],"history":[]},
		"ZERO":{"id":"ZERO","initial":10000,"remaining":0,"holder":"h","location":"l","children":[],"history":[]}
	},"transfers":{}}`)
	if err != nil {
		t.Fatalf("合法边界应打开: %v", err)
	}
	z, err := s.GetSample("ZERO")
	if err != nil {
		t.Fatal(err)
	}
	if z.Remaining != "0.000" || z.Destruction != nil {
		t.Fatalf("零剩余量旧记录应保持未销毁: %+v", z)
	}
}
